import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import Button from '../../components/common/Button';
import Modal from '../../components/common/Modal';
import { ROLES } from '../../utils/constants';

export default function Users() {
  const [users, setUsers] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [form, setForm] = useState({ username: '', email: '', role: ROLES.MEMBER, phone: '', address: '' });
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const { data } = await api.get('/auth/users/');
      setUsers(data.results || data);
    } catch {
      setMessage('Failed to load users');
    }
  };

  const openCreate = () => {
    setEditingUser(null);
    setForm({ username: '', email: '', role: ROLES.MEMBER, phone: '', address: '' });
    setModalOpen(true);
    setMessage('');
  };

  const openEdit = (u) => {
    setEditingUser(u);
    setForm({ username: u.username, email: u.email, role: u.role, phone: u.phone || '', address: u.address || '' });
    setModalOpen(true);
    setMessage('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage('');
    try {
      const payload = { ...form, role: form.role };
      if (editingUser) {
        await api.put(`/auth/users/${editingUser.id}/`, payload);
        setMessage('User updated successfully');
      } else {
        await api.post('/auth/register/', { ...payload, password: 'tempPass123' });
        setMessage('User created successfully');
      }
      setModalOpen(false);
      fetchUsers();
    } catch {
      setMessage('Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this user?')) return;
    try {
      await api.delete(`/auth/users/${id}/`);
      setUsers(users.filter((u) => u.id !== id));
    } catch {
      setMessage('Delete failed');
    }
  };

  return (
    <div className="admin-page">
      <div className="page-header">
        <h1>User Management</h1>
        <Button onClick={openCreate}>Add User</Button>
      </div>

      {message && <p className="message">{message}</p>}

      <table className="users-table">
        <thead>
          <tr>
            <th>Username</th>
            <th>Email</th>
            <th>Role</th>
            <th>Phone</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((u) => (
            <tr key={u.id}>
              <td>{u.username}</td>
              <td>{u.email}</td>
              <td><span className={`role-badge role-${u.role}`}>{u.role}</span></td>
              <td>{u.phone || '-'}</td>
              <td className="actions">
                <button className="btn-text" onClick={() => openEdit(u)}>Edit</button>
                <button className="btn-text btn-danger" onClick={() => handleDelete(u.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title={editingUser ? 'Edit User' : 'Add User'}>
        <form onSubmit={handleSubmit} className="modal-form">
          <input
            placeholder="Username"
            value={form.username}
            onChange={(e) => setForm({ ...form, username: e.target.value })}
            required
          />
          <input
            type="email"
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
            required
          />
          <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
            <option value={ROLES.ADMIN}>Admin</option>
            <option value={ROLES.LIBRARIAN}>Librarian</option>
            <option value={ROLES.MEMBER}>Member</option>
          </select>
          <input
            placeholder="Phone"
            value={form.phone}
            onChange={(e) => setForm({ ...form, phone: e.target.value })}
          />
          <textarea
            placeholder="Address"
            value={form.address}
            onChange={(e) => setForm({ ...form, address: e.target.value })}
          />
          <Button type="submit">{editingUser ? 'Update' : 'Create'}</Button>
          {message && <p className="message">{message}</p>}
        </form>
      </Modal>
    </div>
  );
}
